import{_ as a,o as e,c as d,a4 as s}from"./chunks/framework.vNSRaLQv.js";const b=JSON.parse('{"title":"海思 HI3798MV100 盒子调优记录","description":"","frontmatter":{"title":"海思 HI3798MV100 盒子调优记录","date":"2026-07-19T00:00:00.000Z"},"headers":[],"relativePath":"posts/盒子调优记录.md","filePath":"posts/盒子调优记录.md"}'),i={name:"posts/盒子调优记录.md"};function o(l,t,r,n,c,h){return e(),d("div",null,[...t[0]||(t[0]=[s(`<h1 id="海思-hi3798mv100-盒子调优记录" tabindex="-1">海思 HI3798MV100 盒子调优记录 <a class="header-anchor" href="#海思-hi3798mv100-盒子调优记录" aria-label="Permalink to &quot;海思 HI3798MV100 盒子调优记录&quot;">​</a></h1><h2 id="环境" tabindex="-1">环境 <a class="header-anchor" href="#环境" aria-label="Permalink to &quot;环境&quot;">​</a></h2><ul><li>芯片: HI3798MV100 (hi3798mdmo1g)</li><li>系统: Ubuntu 20.04 LTS (海纳思 ecoo 第三方固件)</li><li>内存: 1GB</li><li>存储: 6.4GB eMMC</li><li>IP: 192.168.31.82</li></ul><h2 id="串口连接" tabindex="-1">串口连接 <a class="header-anchor" href="#串口连接" aria-label="Permalink to &quot;串口连接&quot;">​</a></h2><ul><li>使用 FT232 USB-TTL 转串口</li><li>波特率: 115200</li><li>主机: <code>screen /dev/ttyUSB0 115200</code></li></ul><h2 id="⚠️-翻车教训-不要用-dd-改-bootargs" tabindex="-1">⚠️ 翻车教训: 不要用 dd 改 bootargs <a class="header-anchor" href="#⚠️-翻车教训-不要用-dd-改-bootargs" aria-label="Permalink to &quot;⚠️ 翻车教训: 不要用 dd 改 bootargs&quot;">​</a></h2><p>直接 dd 写 <code>/dev/mmcblk0p2</code>(bootargs 分区) 极其危险:</p><ul><li>CRC 校验不对 → U-Boot 用默认值启动</li><li>参数写错(如 <code>mmz=ddr,0,0,0</code>) → 盒子变砖</li><li>备份存在盒子里 → 砖了也拿不到</li></ul><p><strong>正确方法: 串口进 U-Boot(fastboot) 改环境变量</strong></p><h2 id="bootargs-调优-—-释放-mmz-内存" tabindex="-1">bootargs 调优 — 释放 mmz 内存 <a class="header-anchor" href="#bootargs-调优-—-释放-mmz-内存" aria-label="Permalink to &quot;bootargs 调优 — 释放 mmz 内存&quot;">​</a></h2><h3 id="原始状态" tabindex="-1">原始状态 <a class="header-anchor" href="#原始状态" aria-label="Permalink to &quot;原始状态&quot;">​</a></h3><ul><li><code>mem=1G mmz=ddr,0,0,256M</code> — 解码器吃掉 256M</li><li>系统可用: ~723MB</li></ul><h3 id="优化-mmz-从-256m-→-16m" tabindex="-1">优化: mmz 从 256M → 16M <a class="header-anchor" href="#优化-mmz-从-256m-→-16m" aria-label="Permalink to &quot;优化: mmz 从 256M → 16M&quot;">​</a></h3><p>在 fastboot 提示符执行:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>setenv bootargs_1G mem=1G mmz=ddr,0,0,16M vmalloc=500M</span></span>
<span class="line"><span>saveenv</span></span>
<span class="line"><span>run bootcmd</span></span></code></pre></div><p><strong>效果:</strong> 系统可用从 723MB → ~960MB，省 240MB</p><h3 id="其他模板-可选" tabindex="-1">其他模板(可选) <a class="header-anchor" href="#其他模板-可选" aria-label="Permalink to &quot;其他模板(可选)&quot;">​</a></h3><ul><li>512M 内存: <code>bootargs_512M</code></li><li>768M 内存: <code>bootargs_768M</code></li><li>1G 内存(本机): <code>bootargs_1G</code></li><li>2G 内存: <code>bootargs_2G</code></li><li>3840M(仅限 4G 内存): <code>bootargs_3840M</code></li></ul><h2 id="改-mac-地址" tabindex="-1">改 MAC 地址 <a class="header-anchor" href="#改-mac-地址" aria-label="Permalink to &quot;改 MAC 地址&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>setenv ethaddr AA:BB:CC:DD:EE:FF</span></span>
<span class="line"><span>saveenv</span></span></code></pre></div><h2 id="磁盘清理" tabindex="-1">磁盘清理 <a class="header-anchor" href="#磁盘清理" aria-label="Permalink to &quot;磁盘清理&quot;">​</a></h2><ul><li>swapfile 513M — <code>swapoff /swapfile &amp;&amp; rm -f /swapfile</code> (0 使用纯浪费)</li><li>apt 缓存 — <code>apt clean</code></li><li>日志 — <code>journalctl --vacuum-time=3d</code></li><li>清理后从 1.7G → 1.1G 使用量</li></ul><h2 id="分区表-原始-连续排列" tabindex="-1">分区表(原始, 连续排列) <a class="header-anchor" href="#分区表-原始-连续排列" aria-label="Permalink to &quot;分区表(原始, 连续排列)&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>fastboot   0M    1M</span></span>
<span class="line"><span>bootargs   1M    1M</span></span>
<span class="line"><span>baseparam  2M    4M</span></span>
<span class="line"><span>pqparam    6M    4M</span></span>
<span class="line"><span>logo      10M    4M</span></span>
<span class="line"><span>kernel    14M   20M</span></span>
<span class="line"><span>recovery  34M   64M</span></span>
<span class="line"><span>backup    98M  512M</span></span>
<span class="line"><span>rootfs   610M   -(剩余)</span></span></code></pre></div><p><strong>分区连续无间隙，无法合并。</strong> 要合并需重刷全盘，风险不划算。</p><h2 id="反后门-—-清理-ecoo-私货" tabindex="-1">反后门 — 清理 ecoo 私货 <a class="header-anchor" href="#反后门-—-清理-ecoo-私货" aria-label="Permalink to &quot;反后门 — 清理 ecoo 私货&quot;">​</a></h2><p>海纳思(ecoo.top)固件夹带大量私货:</p><h3 id="已清除的服务-包" tabindex="-1">已清除的服务/包 <a class="header-anchor" href="#已清除的服务-包" aria-label="Permalink to &quot;已清除的服务/包&quot;">​</a></h3><table tabindex="0"><thead><tr><th>服务</th><th>作用</th><th>状态</th></tr></thead><tbody><tr><td>register-api</td><td>开机上报硬件ID到 <code>register-api.ecoo.top:8000</code></td><td>已删</td></tr><tr><td>frpc</td><td>反向 SSH 隧道到 <code>slitaz.tk:7000</code></td><td>已删</td></tr><tr><td>histb-init</td><td>首次开机自动执行脚本框架</td><td>已删</td></tr><tr><td>histb-hello</td><td>每此登录显示版权的 MOTD 横幅</td><td>已删</td></tr><tr><td>histb-config</td><td>系统配置工具</td><td>已删</td></tr><tr><td>bootargs-histb</td><td>修改 bootargs 工具</td><td>已删</td></tr><tr><td>vipupgrade</td><td>&quot;专业版&quot;付费墙</td><td>已删</td></tr><tr><td>vlmcsd</td><td>KMS Windows 激活服务器(盗版)</td><td>已删</td></tr><tr><td>install-*</td><td>一键安装脚本(占位)</td><td>已删</td></tr><tr><td>profile.d 脚本</td><td>登录时弹出版权声明</td><td>已删</td></tr><tr><td>ddnsto</td><td>远程隧道</td><td>已删</td></tr><tr><td>kaitong-frp</td><td>FRP 开通工具</td><td>已删</td></tr></tbody></table><h3 id="保留的工具-可能有用" tabindex="-1">保留的工具(可能有用) <a class="header-anchor" href="#保留的工具-可能有用" aria-label="Permalink to &quot;保留的工具(可能有用)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>工具</th><th>用途</th></tr></thead><tbody><tr><td>Docker + install-docker</td><td>容器</td></tr><tr><td>tailscale</td><td>VPN</td></tr><tr><td>ttyd</td><td>Web 终端</td></tr><tr><td>samba / vsftpd / nfs-server</td><td>文件共享</td></tr><tr><td>transmission</td><td>下载</td></tr><tr><td>filebrowser / alist</td><td>文件管理</td></tr><tr><td>aliyunpan</td><td>云盘同步</td></tr><tr><td>aria2</td><td>下载</td></tr></tbody></table><h3 id="清理后状态" tabindex="-1">清理后状态 <a class="header-anchor" href="#清理后状态" aria-label="Permalink to &quot;清理后状态&quot;">​</a></h3><ul><li>监听端口: 仅 22(SSH) + 53(DNS)</li><li>运行服务: 仅系统标准服务</li><li>磁盘: 1.1G/6.4G 已用, 5.1G 空余</li><li>内存: ~960MB 可用</li></ul>`,33)])])}const m=a(i,[["render",o]]);export{b as __pageData,m as default};
